import { FC } from 'react';
import { ComponentsData } from '../../types';
import { formatDate } from '../../utils';
import './WorkExperience.css';

export const WorkExperience: FC<ComponentsData['workExperience']> = ({
  title,
  data,
}) => {
  return (
    <section className='workExperience'>
      <h2 className='uppercase'>{title}</h2>
      <div className='items'>
        {data.map(({ title, company, projects, startDate, endDate }) => {
          console.log(projects);
          return (
            <div className='item' key={title + startDate}>
              <h5>{title}</h5>
              <a href={company.url} target='_blank' rel='noreferrer'>
                {company.name}
              </a>
              <div className='date'>{formatDate(startDate, endDate)}</div>
              <div className='projects'>
                {projects.map((project) => {
                  return (
                    <div>
                      <a href={project.href} target='_blank' rel='noreferrer'>
                        <div className='projectDescription'>
                          {project.projectDescription}
                        </div>
                      </a>
                      {project.skills.map((skill) => {
                        return <span className='skill'>{skill}</span>;
                      })}
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
};
